-- Reverse of the demo home seed. The home row itself stays:
-- auto-provisioning and the rules-engine seed depend on the fixed id;
-- only its demo metadata is reverted. Entity and twin_state rows go away
-- through the devices cascade.

DELETE FROM twin_relations WHERE id IN (
    '40000000-0000-0000-0000-000000000001',
    '40000000-0000-0000-0000-000000000002',
    '40000000-0000-0000-0000-000000000003',
    '40000000-0000-0000-0000-000000000004',
    '40000000-0000-0000-0000-000000000005'
);

