-- Routes the up migration seeded for the simulated sensors; only present
-- when its blocks actually ran.
DELETE FROM device_registry
WHERE gateway_id = '00000000-0000-0000-0000-000000000001'
  AND external_id IN ('00000000-0000-0000-0000-000000000001',
                      '00000000-0000-0000-0000-000000000002');

